func TestConfirmTrailDeletion(t *testing.T) {
	t.Parallel()

	// --force proceeds without prompting (no TTY needed).
	var buf bytes.Buffer
	proceed, err := confirmTrailDeletion(t.Context(), &buf, 575, "Some title", true, false)
