9		"github.com/entireio/cli/internal/coreapi"
10	)
11	
12	// Control-plane commands reference orgs and projects by their parent ULID in
13	// many places (repo create --project, project create --owner, grant org/project
14	// <id>, …). ULIDs are unfriendly to type, so these refs also accept a human
15	// name: looksLikeULID decides which form was given, and the resolveXRef helpers
16	// turn a name into its ULID via a list lookup. A ULID is always passed straight
17	// through with no network call, preserving the original behavior exactly.
18	
19	// looksLikeULID reports whether s has the shape of a ULID: 26 characters drawn
20	// from Crockford base32 (digits plus uppercase letters, excluding I, L, O, U).
21	// The check is shape-only and case-insensitive on the alphabet; it never hits
22	// the network. A name that happened to be 26 valid base32 characters would be
23	// misread as an id, but real org/project names don't take that form, and the
24	// user can always fall back to the explicit ULID.
25	func looksLikeULID(s string) bool {
26		if len(s) != 26 {
27			return false
28		}
29		for _, r := range strings.ToUpper(s) {
30			switch {
31			case r >= '0' && r <= '9':
32			case r >= 'A' && r <= 'Z' && r != 'I' && r != 'L' && r != 'O' && r != 'U':
33			default:
34				return false
35			}
36		}
37		return true
38	}
39	
40	// resolveOrgRef turns an org reference (ULID or name) into its ULID. A ULID is
41	// returned unchanged; a name is looked up against the caller's visible orgs.
42	func resolveOrgRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
43		if looksLikeULID(ref) {
44			return ref, nil
45		}
46		out, err := c.ListOrgs(ctx)
47		if err != nil {
48			return "", err
49		}
50		return pickOrg(out.Orgs, ref)
51	}
52	
53	// resolveAccountRef turns an account reference into its ULID. A ULID passes
54	// through unchanged; otherwise the ref is a provider-qualified handle (e.g.
